  .setName('ban')
  .setDescription('Ban a user from the server')
  .addUserOption(option => option
    .setName('user')
    .setDescription('The user to ban')
    .setRequired(true))
  .addIntegerOption(option => option
    .setName('days')
    .setDescription('The number of days to ban the user for')
    .setDefault(1)
    .setRequired(false));

client.on('messageCreate', async message => {
  if (!message.content.startsWith('!')) return;

  const args = message.content.slice(1).split(' ');
  const [_, user, days] = args;

  if (!user || !days) return message.reply('Please provide a user and a number of days to ban them for.');

  const userId = message.guild.members.cache.get(user);
  if (!userId) return message.reply(`User ${user} not found.`);

  const banDuration = parseInt(days) * 86400000; // convert days to milliseconds
  await userId.ban({ days: banDuration });

  message.reply(`User ${user} has been banned for ${days} days.`);
});

client.commands.set(banCommand.data.name, banCommand);

client.login('YOUR_BOT_TOKEN_HERE');
```
