// This will give an error, because the type system doesn't know
// that value will always be a string
console.log(value.toUpperCase());

// This will work, because we're asserting that value is a string
console.log(value.toUpperCase() as string);
```
You can also use a type assertion in conjunction with an interface or type to provide more specific information about the type of a value. For example:
```
interface MyValue {
  value: string;
}

let value: MyValue = { value: "hello" };

// This will give an error, because the type system doesn't know
// that value.value is always a string
console.log(value.value.toUpperCase());

// This will work, because we're asserting that value.value is a string
console.log(value.value.toUpperCase() as string);
```
